  str_quest_base_story_new_chapter_open = "새 챕터 퀘스트 개방",
  str_quest_base_daily_reset_tips = "일일 퀘스트 초기화 완료",
  str_quest_base_awards_info_look = "미리보기",
  str_quest_base_story_chapter_index = "제%s챕터",
  str_quest_base_story_all_chapter_clean = "모든 챕터 퀘스트 완료!",
  str_quest_base_story_current_chapter_clean = "해당 챕터 퀘스트 완료",
  str_quest_base_story_click_lock_chapter = "이전 스토리 퀘스트 완료 후 개방",
  str_quest_base_desc_101 = "스카이워커호의 주인이여, 이것은 항해의 출발점이다. 의외의 수확, 갑작스러운 사고, 새로운 전환점, 그리고 피치 못할 성장... 강해진다는 것은 고통을 동반하기 마련이다. 피할 수 없다면, 즐겨라. 미래에는 이 모든 고난의 대가를 받게 될 것이다. ──베들레헴",
  str_quest_base_desc_102 = "세계에 처음 들어온 느낌이 무척이나 묘하겠지. 부디 그대가 침착하고 이성적으로 위기에 대응하고, 인연을 소중히 여기길 바란다. 그대가 만나게 되는 모든 것들은 이 아스트라의 일부이자, 마지막엔 오로라로 돌아가게 될 것들이다. 그대 자신도 말이지... 받아들이고, 이해하고, 반응하고, 그리고 계속 성장해라. ──베들레헴",
  str_quest_base_desc_103 = "과거로부터의 울림이 다시금 일렁이며, 동료, 적, 전우를 통해 쉴 새 없이 이어졌다. 희망의 조짐과 추락의 좌절을 마주하는 법, 자신의 원한과 새로운 집단의 「사명」 사이에서 균형을 맞추는 법, 모두 그대의 피와 눈물을 통해 알아내야 하는 것들이다. ──베들레헴",
  str_quest_base_desc_104 = "이제, 그대의 목표를 이해하였느냐. 종족이 아닌 다른 이들로부터 인정받는 것을 느꼈느냐. 이 앞에는 오로리안의 최후의 도시, 하늘과 맞닿은 공중의 섬이 있다. 그대는 이곳에서 새로운 인연을 찾게 될 것이며, 어둠을 무너뜨리기 위해 더욱 굳건한 발걸음을 한발 더 내딛게 될 것이다. ──베들레헴",
  str_quest_base_desc_105 = "끊임없이 좌절하고, 끊임없이 싸워나가라. 태어나서 한 번도 물러서 본 적 없는 맹수처럼, 검을 휘두르며 죽음을 무서워하지 않는 용감한 자처럼. 과거는 계속해서 엄습할 것이며, 그대는 가장 큰 공포를 마주하게 될 것이다. 그녀의 얼굴을 보며 말해 주거라. 그대가 눈에 담고 있는 자가 누구인지 말이다. ──베들레헴",
  str_quest_base_desc_106 = "초조한가? 오로라가 보여준 것처럼, 그대는 곧 밑바닥에 이르게 될 것이다. 그곳은 울분과 증오가 모인 수렁이자, 실패와 치욕이 만들어낸 감옥이다. 그러나 그곳을 거쳐야지만 진정한 힘을 얻어낼 수 있다. 강철 같은 몸이 아니라, 열린 눈과 마음이라는 힘을 말이지. ──베들레헴",
  str_quest_base_desc_107 = "우리의 대화가 드디어 새로운 단계를 맞이했구나, 아이테르여. 그대는 내 역할을 이해하지 못하겠지. 그것은 나도 마찬가지다. 짧은 추상적인 기록에 의지한 탓이리라. 오로라는 어둠에 빠졌고, 백야성 위에는 절망을 품은 자가 날개를 펼치고 있다. 남은 것은 그대의 선택이다. 그녀를 이겨내거나, 아니면 여기서 포기하거나. ──베들레헴",
  str_quest_base_desc_108 = "가장 어두운 심연 속에서도, 그대는 「예언」을 검증하는 그날까지 살아남을 수 있겠지. 내가 믿는 것은 말로 설명할 수 없는 마음과 직감이다. 기회를 잡거라. 아이테르여, 어둠의 요새를 그들이 있어야 할 곳으로 돌려보내라. ──베들레헴",
  str_quest_base_desc_109 = "우리에게는 두 개의 고향이 있다. 하나는 발아래에, 다른 하나는 마음에 있지. 운이 좋은 자들은 그 둘이 사실은 다를 것이 없음을 깨닫겠지만, 대부분의 고통받는 영혼들은 둘 사이에서 끊임없이 고통스러워하고, 심지어는 기억 깊은 곳의 그 땅을 밟을 기회조차 얻지 못하지. 비록 내키진 않겠지만, 다른 방법은 없을 것이다. ──베들레헴",
  str_quest_base_desc_110 = "나는 그 땅이 그대를 성장하게 하고, 많은 것을 기억하게 하고, 또한 평온하게 모든 것을 내려놓을 수 있게 하리라 믿는다. 여정의 끝이 눈앞에 있다. 분노와 증오를 마음껏 발산하고, 모든 것을 연기처럼 사라지도록 놓아주거라. 부디 우리가 만나기 전까지, 그대가 새로운 모습으로 태어났기를 바라마. ──베들레헴",
  str_quest_base_desc_111 = "영원한 밤, 그것은 모든 오로리안이 다가가려 하지 않는 영역, 어둠에 침식된 심연이다. 부디 이 낮과 밤의 막간에서 그 찰나의 기회를 잡길 바란다. 콜로서스의 주인이여, 어둠을 뚫고 마침내 원하는 것을 손에 넣길 바라마. ──베들레헴",
  str_quest_base_desc_112 = "희망은 종종 가시덤불에서 태어나는 꽃송이처럼 시련을 동반한다. 상처투성이가 될 준비가 되어 있다면, 다시 그대가 출발한 곳으로 돌아가라. 찾고, 잃고, 절망하고, 다시 그대의 고개를 들어라. ──베들레헴",
  str_quest_base_desc_113 = "진실의 예리한 칼날이 가슴을 꿰뚫고, 연약한 심방을 찢어가른다. 「어째서 이럴 수 있지?」, 「이럴 순 없어!」, 의아, 의심, 울분, 그리고 잃어버린 심연에서 허공을 응시하지. 나는 그대의 선택이 보이지 않는다. 아이테르여, 내게는 아무것도 보이지 않는다. ──베들레헴",
  str_quest_base_desc_114 = "모든 이는 자신의 삶에서 끊임없이 지식을 찾는다. 그대에게는 행운이 있으나, 비애도 함께한다. 운명은 그대를 위해 더 넓은 공간을 남겼고, 그대는 보통의 사람들보다 더 멀리 나아갈 수 있을 것이다. 그러나 그 길에는 다른 이가 없구나. 나는 그대가 어디로 나아갈지 알지 못한다. 운명이 그대를 내 시야의 바깥으로 인도할 것이기 때문이지. ──베들레헴",
  str_quest_base_desc_115 = "알고 있느냐, 그대는 점차 더 많은 사람들을 만나기 시작했구나. 그들은 다른 곳에서 와서 다른 곳으로 향하며, 그저 그 길의 어딘가에서 그대와 마주쳤을 뿐이다. 창궁 아래에는 저토록 많은 이들이 살고 있고, 머리 위에 태양을 든 행운아들은 가장 풍족한 햇살을 누리고 있지. 허나 황혼의 석양 곁에 선 아이들이야말로 태양에 가장 가까이 서 있는 법이다. ──베들레헴",
  str_quest_base_desc_116 = "오랜 적과 함께 걷는 것은 참으로 아이러니한 운명이지. 앞에 있는 것이 불바다든, 깊은 구덩이든, 그대에게 주어진 선택은 동료들과 함께 마주하는 것뿐이다. ──베들레헴",
  str_quest_base_desc_117 = "전장은 음모자들의 무대, 무지한 구경꾼들은 사방에서 몰려든다. 끝없는 밤이 다가오고 있는데도 오로리안들은 아직 각자의 단꿈에서 진정으로 깨어나지 못한 채로구나. ──베들레헴",
  str_quest_base_desc_118 = "권력이 옮겨 가는 순간, 지금껏 운명이 굽어보지 않던 이가 모두의 주목 가운데 세상이란 무대에 올랐구나. 허나, 야심은 전장에서 가장 무용한 병기이지. 스스로 옛 자신의 목숨을 빼앗아야만, 정치의 소용돌이에서 벗어나 새 생명을 얻을 수 있을 것이다. ──베들레헴",
  str_quest_base_desc_119 = "힘이라는 것은 나에게서 비롯되는 것인가, 아니면 타인에게서 부여받는 것인가. 강대한 육체가 늪에서 힘겹게 무덤을 파고 있는 모습을 보고 나면, 그대는 차차 생명의 본질이란 나약함이란 것을 깨닫게 될 테지. ──베들레헴",
  str_quest_base_desc_120 = "한 낯선 존재가 600년의 시간을 넘어 마침내 일루미나와 악수를 나누었구나. 역사의 페이지를 넘기고 가능성을 찾아야 할까, 아니면 과거를 버리고 새로운 길을 만들어야 할까. 이것은 현재의 질문이자, 무수한 세대의 오로리안들을 괴롭혀 온 수수께끼이기도 하지. ──베들레헴",
  str_quest_base_desc_121 = "동료들과 많은 즐거운 시간을 보내면서, 작별의 시간이 이토록 급히 다가올 줄은 그대도 몰랐을 것이다. 「과거에서 온 신호」가 다시 켜졌다. 이제 그대는 반드시 성장해서, 미지의 유적으로 향해 그대의 과거를 탐색해야 한다. ──베들레헴",
  str_quest_base_desc_122 = "나아갈 앞길에 등대를 세워라. 그것이 나 북방의 여왕의 선언이다. ──베들레헴",
  str_quest_base_type_stroy_with_space = "스토리",
  str_quest_base_type_daily_with_space = "일일",
  str_quest_base_type_side_with_space = "서브",
