  str_quest_base_achieve_finish_list_title = "다음 임무를 완료했습니다",
  str_quest_base_desc_123 = "그대는 이미 극야를 알았다. 마음속 신념은 명확히 하였느냐. 이 세상에는 너무나도 많은 사람이 어둠의 국면에 빠져 막연한 희망을 쫓고 있다. 그러나 그대에게는 그것이 결코 허상이 아닐 것이다. 그대는 끝내 그 희망을 잡을 것이다. 그 이유인즉 이 이야기는 그대가 이 영웅의 길을 나섰을 때 시작되었기 때문이다. 그대는 그 빛을 지킬 것이고, 희망 또한 그대를 위해 이어질 것이다. 이 점을 믿고, 계속해서 흔들리지 말고 나아가라. ──베들레헴",
